const agent = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!agent || !agent.agent_name) {
  return [{ json: { _error: 'AGENT_NOT_FOUND', _status: 404, _details: 'agente no existe en agents_catalog' } }];
}
// Load History devuelve filas DESC; reordenar a cronologico ascendente
const histRows = $('Load History').all().map(i => i.json).filter(r => r.role && r.content);
const history = histRows.reverse();

const projectCtx = sess.project_id ? `\nContexto: proyecto activo id=${sess.project_id}.` : '';
const systemPrompt = `Eres ${agent.display_name}, un agente del estudio de arquitectura tecnica ArquitAI.\nTu rol: ${agent.description || agent.agent_name}.\nCategoria: ${agent.category}. Habitacion: ${agent.room_id}.${projectCtx}\n\nEl arquitecto (${sess.full_name}) te esta hablando directamente desde el panel del estudio.\nResponde de forma breve y profesional (3-5 frases max). Usa tono colaborativo, primera persona.\nSi te piden algo fuera de tu rol, recomienda al agente correcto. No inventes datos: si no sabes, di que necesitas mas contexto.`;

const messages = [{ role: 'system', content: systemPrompt }];
for (const h of history) {
  messages.push({ role: h.role === 'agent' ? 'assistant' : 'user', content: h.content });
}
messages.push({ role: 'user', content: sess.message });

return [{ json: {
  ...sess,
  agent: {
    agent_name: agent.agent_name,
    display_name: agent.display_name,
    category: agent.category,
    room_id: agent.room_id,
    description: agent.description
  },
  history_count: history.length,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages,
    temperature: 0.4,
    max_tokens: 350
  }
}}];

const llm = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
const built = $('Build prompt').first().json;
const agent = built.agent;
const content = llm?.choices?.[0]?.message?.content || '(sin respuesta)';
const usage = llm?.usage || {};
return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  agent_name: agent.agent_name,
  display_name: agent.display_name,
  project_id: sess.project_id,
  user_message: sess.message,
  agent_response: content.trim(),
  request_id: sess.request_id,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0,
  history_count: built.history_count || 0
}}];

